package uz.mirix.tracelens.internal;
import uz.mirix.tracelens.*;import java.util.Locale;
public final class TraceReportFormatter {private TraceReportFormatter(){}public static String format(TraceReport r,TraceLensProperties p){StringBuilder out=new StringBuilder(256);out.append("TraceLens ").append(r.method()).append(' ').append(r.route()).append("  ").append(r.status()).append("  ").append(ms(r.durationNanos())).append(" ms");if(p.getLogging().isIncludeTraceId())out.append("  [trace=").append(r.traceId()).append(']');if(r.truncated())out.append("  [spans-truncated]");if(r.errorType()!=null)out.append("  [error=").append(r.errorType()).append(']');for(int i=0;i<r.spans().size();i++){TraceSpan s=r.spans().get(i);out.append(System.lineSeparator()).append(i==r.spans().size()-1?"└─ ":"├─ ").append(s.name()).append("  ").append(ms(s.durationNanos())).append(" ms");}return out.toString();}private static String ms(long nanos){return String.format(Locale.ROOT,"%.2f",nanos/1_000_000.0d);}}
